#nullable enable // autogenerated  
  
using System.Collections.Generic;  
using MVZ2.GameContent.Bosses;  
using MVZ2.GameContent.Buffs;  
using MVZ2.GameContent.Buffs.Enemies;  
using MVZ2.GameContent.Effects;  
using MVZ2.GameContent.Pickups;  
using MVZ2.Vanilla.Audios;  
using MVZ2.Vanilla.Entities;  
using MVZ2.Vanilla.Properties;  
using MVZ2Logic.Entities;  
using MVZ2Logic.Level;  
using PVZEngine;  
using PVZEngine.Auras;  
using PVZEngine.Buffs;  
using PVZEngine.Damages;  
using PVZEngine.Definitions;  
using PVZEngine.Entities;  
using Tools;  
using UnityEngine;  
  
namespace MVZ2.GameContent.Enemies  
{  
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.balloon)]  
    public class Balloon : EntityBehaviourDefinition  
    {  
        public Balloon(string nsp, string name) : base(nsp, name)  
        {  
            AddAura(new DragAura());  
        }  
  
        public override void Init(Entity entity)  
        {  
            base.Init(entity);  
            var buff = entity.AddBuff<FlyBuff>();  
            buff.SetProperty(FlyBuff.PROP_TARGET_HEIGHT, 120f);  
  
            var buff2 = entity.AddBuff<RadiationProtection>();  
            buff2.SetProperty(RadiationProtection.PROP_Protection_Level, 1f);  
  
            // 首次生成时随机分配一个气球形态并应用效果；从存档恢复时只刷新贴图。  
            if (!IsTypeAssigned(entity))  
            {  
                var type = RollBalloonType(entity.RNG);  
                SetBalloonType(entity, type);  
                SetTypeAssigned(entity, true);  
                ApplyBalloonType(entity);  
            }  
            else  
            {  
                // 恢复贴图  
                entity.SetModelProperty(PROP_MODEL_KEY, GetBalloonType(entity));  
            }  
        }  
  
        public override void Update(Entity entity)  
        {  
            base.Update(entity);  
            if (entity.Parent != null)  
            {  
                DragParent(entity, entity.Parent);  
            }  
        }  
  
        public override void PostDeath(Entity entity, DeathInfo deathInfo)  
        {  
            base.PostDeath(entity, deathInfo);  
            var parent = entity.Parent;  
            if (parent != null && parent.IsEntityOf(VanillaBossID.lockedChest))  
            {  
                LockedChest.Stun(parent, 10);  
            }  
  
            // 被直接移除（如换场、REMOVE_ON_DEATH）时不触发掉落/生成效果。  
            if (entity.WillRemoveOnDeath(deathInfo))  
                return;  
  
            switch (GetBalloonType(entity))  
            {  
                // 白色：普通气球，无额外效果  
                case TYPE_WHITE:  
                    break;  
                // 红色：打破后掉红石  
                case TYPE_RED:  
                    DropPickups(entity, VanillaPickupID.redstone, RED_DROP_COUNT);  
                    break;  
                // 黄色：打破后掉钱（绿宝石）  
                case TYPE_YELLOW:  
                    DropPickups(entity, VanillaPickupID.emerald, YELLOW_DROP_COUNT);  
                    break;  
                // 绿色：打破后概率生成怪物  
                case TYPE_GREEN:  
                    if (entity.RNG.NextFloat() < GREEN_SPAWN_CHANCE)  
                    {  
                        SpawnRandomEnemy(entity);  
                    }  
                    break;  
                // 紫色：打破后在地面生成木乃伊毒气  
                case TYPE_PURPLE:  
                    SpawnMummyGas(entity);  
                    break;  
            }  
        }  
  
        public static void DragParent(Entity entity, Entity parent)  
        {  
            parent.SetCenter(entity.Position + Vector3.back * 3);  
        }  
  
        #region 形态应用  
        private void ApplyBalloonType(Entity entity)  
        {  
            var type = GetBalloonType(entity);  
            // 切换贴图：模型端需要根据该 int 属性选择对应贴图。  
            entity.SetModelProperty(PROP_MODEL_KEY, type);  
  
            // 蓝色气球速度更快。  
            if (type == TYPE_BLUE)  
            {  
                var speedBuff = entity.AddBuff<RandomEnemySpeedBuff>();  
                RandomEnemySpeedBuff.SetSpeed(speedBuff, BLUE_SPEED_MULTIPLIER);  
            }  
        }  
  
        private static int RollBalloonType(RandomGenerator rng)  
        {  
            var index = rng.WeightedRandom(TypeWeights);  
            return BalloonTypes[index];  
        }  
        #endregion  
  
        #region 掉落 / 生成  
        private void DropPickups(Entity entity, NamespaceID pickupID, int count)  
        {  
            for (int i = 0; i < count; i++)  
            {  
                entity.Level.Spawn(pickupID, entity.Position + Vector3.up * 10, entity)?.Let(e =>  
                {  
                    e.Velocity = new Vector3(e.RNG.Next(-1f, 1f), 2, 0);  
                });  
            }  
        }  
  
        private void SpawnRandomEnemy(Entity entity)  
        {  
            var index = entity.RNG.WeightedRandom(SpawnWeights);  
            var enemyID = SpawnPool[index];  
            var spawnParam = entity.GetSpawnParams();  
            spawnParam.SetProperty(EngineEntityProps.FACTION, entity.GetFaction());  
            var pos = entity.Position;  
            pos.y = entity.GetGroundY();  
            entity.Spawn(enemyID, pos, spawnParam);  
        }  
  
        private void SpawnMummyGas(Entity entity)  
        {  
            var param = entity.GetSpawnParams();  
            param.SetProperty(EngineEntityProps.SCALE, entity.GetScale());  
            var pos = entity.Position;  
            pos.y = entity.GetGroundY();  
            entity.Spawn(VanillaEffectID.mummyGas, pos, param);  
            entity.PlaySound(VanillaSoundID.poisonCast);  
        }  
        #endregion  
  
        #region 属性存取  
        public static int GetBalloonType(Entity entity) => entity.GetBehaviourField<int>(PROP_BALLOON_TYPE);  
        public static void SetBalloonType(Entity entity, int value) => entity.SetBehaviourField(PROP_BALLOON_TYPE, value);  
        public static bool IsTypeAssigned(Entity entity) => entity.GetBehaviourField<bool>(PROP_TYPE_ASSIGNED);  
        public static void SetTypeAssigned(Entity entity, bool value) => entity.SetBehaviourField(PROP_TYPE_ASSIGNED, value);  
        #endregion  
  
        public class DragAura : AuraEffectDefinition  
        {  
            public DragAura() : base(VanillaBuffID.Entity.draggedByBalloon, 1)  
            {  
            }  
  
            public override void GetAuraTargets(AuraEffect auraEffect, List<IBuffTarget> results)  
            {  
                var source = auraEffect.Source.GetEntity();  
                if (source == null)  
                    return;  
                if (source.Parent != null)  
                {  
                    results.Add(source.Parent);  
                }  
            }  
        }  
  
        // ===== 形态常量 =====  
        public const int TYPE_WHITE = 0;   // 白色：普通气球  
        public const int TYPE_RED = 1;     // 红色：掉红石  
        public const int TYPE_YELLOW = 2;  // 黄色：掉钱  
        public const int TYPE_BLUE = 3;    // 蓝色：速度更快  
        public const int TYPE_GREEN = 4;   // 绿色：概率生成怪物  
        public const int TYPE_PURPLE = 5;  // 紫色：地面生成木乃伊毒气  
  
        // 各形态出现权重（数值越大越常见）  
        private static int[] BalloonTypes = new int[]  
        {  
            TYPE_WHITE,  
            TYPE_RED,  
            TYPE_YELLOW,  
            TYPE_BLUE,  
            TYPE_GREEN,  
            TYPE_PURPLE,  
        };  
        private static int[] TypeWeights = new int[]  
        {  
            40, // 白  
            10, // 红  
            20, // 黄  
            10, // 蓝  
            10, // 绿  
            10, // 紫  
        };  
  
        // 绿色气球生成怪物的加权池  
        private static NamespaceID[] SpawnPool = new NamespaceID[]  
        {  
            VanillaEnemyID.zombie,  
            VanillaEnemyID.leatherCappedZombie,  
            VanillaEnemyID.ironHelmettedZombie,  
            VanillaEnemyID.flagZombie,  
        };  
        private static int[] SpawnWeights = new int[]  
        {  
            20,  
            10,  
            5,  
            1,  
        };  
  
        // ===== 数值参数 =====  
        public const int RED_DROP_COUNT = 1;  
        public const int YELLOW_DROP_COUNT = 1;  
        public const float BLUE_SPEED_MULTIPLIER = 1.75f;  
        public const float GREEN_SPAWN_CHANCE = 0.5f;  
  
        // 切换贴图用的模型属性名（模型端据此选择贴图）  
        public const string PROP_MODEL_KEY = "BalloonType";  
        public static readonly VanillaEntityPropertyMeta<int> PROP_BALLOON_TYPE = new VanillaEntityPropertyMeta<int>("BalloonType");  
        public static readonly VanillaEntityPropertyMeta<bool> PROP_TYPE_ASSIGNED = new VanillaEntityPropertyMeta<bool>("BalloonTypeAssigned");  
    }  
}
